using System;
using LittleLeo;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

public class RuneInstance : ActionInstance
{
	[Header("Assets")]
	[SerializeField]
	private ActionInstanceData actionInstanceData;

	[Header("Activating Animation")]
	[SerializeField]
	private float moveAmount;

	[SerializeField]
	private float noConditionRuneMoveAmount;

	[SerializeField]
	private float moveDuration;

	[SerializeField]
	private AnimationCurve moveCurve;

	[Header("Rune Instance Components")]
	[SerializeField]
	private RectTransform rect;

	[SerializeField]
	private ActionFaceInstance2D actionFaceInstance2D;

	[SerializeField]
	private PlayerCurrentRunes playerCurrentRunes;

	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	protected CanvasReference dragCanvasReference;

	[SerializeField]
	private CameraReference mainCameraReference;

	[SerializeField]
	private CameraReference dicePreviewCameraReference;

	[SerializeField]
	private GameObject virtueEnableVFXPrefab;

	[Header("Action Description Panel Positioning")]
	[SerializeField]
	private bool positionOverride;

	[SerializeField]
	[ShowIf("positionOverride")]
	private TransformPositionOverride[] transformPositionOverrides;

	[Header("Run Stats")]
	[SerializeField]
	private bool disableActionDescriptionPanelDescription;

	protected Rune rune;

	private Vector3 disabledPosition;

	private Vector3 enabledPosition;

	private Coroutine movementCoroutine;

	private bool isInitialized;

	private RunesPanel runesPanel;

	private Transform holder;

	private int siblingIndex;

	private Vector2 pos;

	private Coroutine dragOutCoroutine;

	private GameObject runeInstanceEnabledVFX;

	public ActionFaceInstance2D ActionFaceInstance2D => actionFaceInstance2D;

	public Rune Rune => rune;

	private void Update()
	{
		if (dragging)
		{
			base.transform.position = GetRuneInstanceConvertedPosition();
		}
	}

	private Vector3 GetRuneInstanceConvertedPosition()
	{
		RectTransformUtility.ScreenPointToLocalPointInRectangle(dragCanvasReference.Value.transform as RectTransform, Input.mousePosition, dragCanvasReference.Value.worldCamera, out pos);
		return dragCanvasReference.Value.transform.TransformPoint(pos);
	}

	protected override void Awake()
	{
		base.Awake();
		InitializeActionInstance(actionInstanceData);
		disableDiscard = false;
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		InvokeAlternatives.InvokeAfterFrame(this, delegate
		{
			holder = base.transform.parent;
		});
	}

	public virtual void Initialize(Rune rune, RunesPanel runesPanel, bool noConditionRune = false)
	{
		actionEnabled = false;
		this.runesPanel = runesPanel;
		actionFaceInstance2D.Initialize(rune.BattleAction, rune.ValueText(rune.ModifiedActionValue), rune.ActionValueModifier > 0);
		actionFaceInstance2D.ToggleActionFace(toggle: false, new Color(0.7f, 0.7f, 0.7f, 1f));
		actionOwner = playerGameObjectReference.value;
		diceOwnerEnum = DiceOwnerEnum.PLAYER;
		ResetScale();
		this.rune = rune;
		actionInstanceOutlineHandler.UpdateOutlineAndMustUse();
		dragging = false;
		InvokeAlternatives.InvokeAfterMultipleFrames(this, 3, delegate
		{
			disabledPosition = base.transform.localPosition;
			InitializeEnabledPosition(noConditionRune);
		});
	}

	public void InitializeEnabledPosition(bool noConditionRune = false)
	{
		if (noConditionRune)
		{
			Vector3 vector = base.transform.localPosition + noConditionRuneMoveAmount * Vector3.up;
			SetEnabledPosition(vector);
		}
		else
		{
			Vector3 vector2 = base.transform.localPosition + moveAmount * Vector3.up;
			SetEnabledPosition(vector2);
		}
	}

	public void SetEnabledPosition(Vector3 value)
	{
		enabledPosition = value;
	}

	private bool RuneActionSelectedCheck()
	{
		if (!CanDrag())
		{
			return false;
		}
		if (base.isOnChooseActionState && !ActionSelectedCheckConditionToBeCastedWithActionValue(playerHand: false))
		{
			return false;
		}
		siblingIndex = base.transform.GetSiblingIndex();
		base.transform.SetParent(dragCanvasReference.Value.transform);
		return true;
	}

	public override bool StartFollowingMouse()
	{
		if (!RuneActionSelectedCheck())
		{
			return false;
		}
		bool result = base.StartFollowingMouse();
		if (runeInstanceEnabledVFX != null)
		{
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(runeInstanceEnabledVFX);
			runeInstanceEnabledVFX = null;
		}
		return result;
	}

	public override void ActionDroppedOnBattleActionCastSpace()
	{
		(actionInstanceOutlineHandler as RuneInstanceOutlineHandler).RemoveHighlightRuneInstance();
		ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
		base.ActionDroppedOnBattleActionCastSpace();
		if (dragOutCoroutine != null)
		{
			StopCoroutine(dragOutCoroutine);
		}
		ToggleOnDragCanvasLayerAndCamera(mainCamera: true);
	}

	public void ToggleOnDragCanvasLayerAndCamera(bool mainCamera)
	{
		dragCanvasReference.Value.worldCamera = (mainCamera ? mainCameraReference.value : dicePreviewCameraReference.value);
		dragCanvasReference.Value.gameObject.layer = (mainCamera ? 5 : 10);
	}

	public void HighlightRuneInstance()
	{
		(actionInstanceOutlineHandler as RuneInstanceOutlineHandler).HighlightRuneInstance();
	}

	public void RemoveHighlightRuneInstance()
	{
		(actionInstanceOutlineHandler as RuneInstanceOutlineHandler).RemoveHighlightRuneInstance();
	}

	public override bool JoystickActionSelected()
	{
		if (!RuneActionSelectedCheck())
		{
			return false;
		}
		return base.JoystickActionSelected();
	}

	public override void GoBackToOriginalPositionAnimation(bool returningToHandAfterDrag = false, Action afterGoBackToOriginalPositionAction = null)
	{
		base.GoBackToOriginalPositionAnimation(returningToHandAfterDrag, afterGoBackToOriginalPositionAction);
		Vector3 startPosition = base.transform.position;
		Vector3 targetPosition = holder.TransformPoint(enabledPosition) - Vector3.right * mainCameraReference.value.transform.position.x;
		if (dragOutCoroutine != null)
		{
			StopCoroutine(dragOutCoroutine);
		}
		dragOutCoroutine = StartCoroutine(CoroutineUtility.CurveRoutine(0.2f, endDragAnimCurve, delegate(float t, float v)
		{
			base.transform.position = Vector3.Lerp(startPosition, targetPosition, v);
		}, delegate
		{
			base.transform.SetParent(holder);
			base.transform.SetSiblingIndex(siblingIndex);
			base.transform.position = base.transform.position + Vector3.right * mainCameraReference.value.transform.position.x;
			AfterGoBackToOriginalPositionAnimation(afterGoBackToOriginalPositionAction);
		}));
	}

	public override void AfterGoBackToOriginalPositionAnimation(Action afterGoBackToOriginalPositionAction = null)
	{
		base.AfterGoBackToOriginalPositionAnimation(afterGoBackToOriginalPositionAction);
		actionInstanceOutlineHandler.ToggleOutline(toggle: true);
		dragOutCoroutine = null;
	}

	public void OnToggleActionButton(bool toggle)
	{
		if (actionEnabled == toggle)
		{
			return;
		}
		if (!isInitialized)
		{
			isInitialized = true;
		}
		actionInstanceOutlineHandler.ToggleOutline(toggle);
		actionEnabled = false;
		actionFaceInstance2D.ToggleActionFace(toggle, new Color(0.7f, 0.7f, 0.7f, 1f));
		Vector3 startPosition = base.transform.localPosition;
		Vector3 targetPosition = (toggle ? enabledPosition : disabledPosition);
		if (movementCoroutine != null)
		{
			StopCoroutine(movementCoroutine);
			movementCoroutine = null;
		}
		movementCoroutine = StartCoroutine(CoroutineUtility.CurveRoutine(moveDuration, moveCurve, delegate(float t, float v)
		{
			rect.localPosition = Vector3.Lerp(startPosition, targetPosition, v);
		}, delegate
		{
			if (toggle && GameScenesUtils.IsBattleScene() && ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled())
			{
				runeInstanceEnabledVFX = ReferenceSingleton<VFXHandler>.Instance.GetVFX(virtueEnableVFXPrefab, base.transform.position, base.transform);
				InvokeAlternatives.Invoke(this, 3f, delegate
				{
					if (runeInstanceEnabledVFX != null)
					{
						ReferenceSingleton<PoolHandler>.Instance.StoreObject(runeInstanceEnabledVFX);
						runeInstanceEnabledVFX = null;
					}
				});
			}
			movementCoroutine = null;
			StoreTrail();
			actionEnabled = toggle;
		}));
	}

	public override void DisposeAction()
	{
		playerCurrentRunes.ActivateCodexOfBurdenOmen();
		base.DisposeAction();
		if (dragOutCoroutine != null)
		{
			StopCoroutine(dragOutCoroutine);
		}
		InvokeAlternatives.InvokeAfterFrame(this, delegate
		{
			base.transform.SetParent(holder);
			base.transform.SetSiblingIndex(siblingIndex);
			OnToggleActionButton(toggle: false);
		});
		InvokeAlternatives.Invoke(this, moveDuration, delegate
		{
			Discarding = false;
		});
		runesPanel.ToggleRuneSlotSprite(toggle: false, rune.index);
		actionInstanceTrailHandler.KillTrail();
		playerCurrentRunes.usedRuneIndexes.Add(rune.index);
		playerCurrentRunes.activeRuneIndexes.Remove(rune.index);
		playerCurrentRunes.refreshedRuneIndexes.Remove(rune.index);
		(actionInstanceOutlineHandler as RuneInstanceOutlineHandler).RemoveHighlightRuneInstance();
	}

	protected override ActionFace GetActionFace()
	{
		return rune;
	}

	public override void InitializeActionDescriptionPanel()
	{
		if (positionOverride)
		{
			actionDescriptionPanel.OverridePositions(transformPositionOverrides);
		}
		base.InitializeActionDescriptionPanel();
		string localizedString = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("Virtue");
		actionDescriptionPanel.Initialize(rune, localizedString);
		if (disableActionDescriptionPanelDescription)
		{
			CheckDisableActionDescriptionPanelDescription();
		}
	}

	protected void CheckDisableActionDescriptionPanelDescription()
	{
		if (rune.BattleAction.name == "EmptyVirtueSlotAction")
		{
			actionDescriptionPanel.DisableActionDescriptionPanelDescription();
		}
	}

	public void UpdateActionFace()
	{
		actionFaceInstance2D.Initialize(rune.BattleAction, rune.ValueText(rune.ModifiedActionValue), rune.ActionValueModifier > 0);
	}

	public void ToggleActionFace(bool toggle)
	{
		actionFaceInstance2D.ToggleActionFace(toggle, new Color(0.7f, 0.7f, 0.7f, 1f));
	}
}
